/**
 * Sweep Stale Worktrees — SessionStart Hook (#1884, narrowed #3353)
 *
 * Removes debris that a failed `Agent(isolation: "worktree")` spawn leaves
 * INSIDE the repo and that `git worktree prune` cannot see, because it was
 * never registered with git:
 *
 *   1. `<projectDir>/.worktrees/<name>/` shells that hold no real file
 *      (`.gitkeep` placeholders ignored), see #2335.
 *   2. `.claude/state/worktree-pending/<name>.json` markers whose recorded
 *      worktree never materialized.
 *
 * History: the hook was born (#1884) to reap sibling `../<repo>-<task>`
 * directories left by aborted `git worktree add` runs. #3319 retired that
 * layout (a sibling sits outside the session's project directory and the
 * harness silently bounces any `cd` into it; worktrees now live at
 * `.worktrees/<task>`), and #3353 removed the sibling-scanning branch here:
 * it walked the PARENT directory of every repo on every SessionStart to find
 * a shape nothing produces any more. This hook never touches paths outside
 * the project directory now.
 *
 * Safety predicates (ALL must hold to delete):
 *   1. Path is NOT in `git worktree list` (genuinely orphaned). If the git
 *      call itself fails the whole sweep is skipped (fail-closed).
 *   2. Path contains zero regular files (nested empty dirs are OK to remove).
 *   3. Path mtime is older than 1 hour (race protection — don't kill a
 *      worktree-add that's currently in flight).
 *
 * Opt-out: set `ORK_NO_STALE_SWEEP=1` to skip entirely.
 *
 * Hook event: SessionStart (async, timeout: 5s)
 */

import type { HookInput, HookResult, HookContext } from '../types.js';
import { outputSilentSuccess } from '../lib/common.js';
import { NOOP_CTX } from '../lib/context.js';
import { existsSync, readFileSync, realpathSync, rmSync, readdirSync, statSync } from 'node:fs';
import { join, resolve } from 'node:path';

import { execFileSync } from 'node:child_process';
import { getProjectDir } from '../lib/paths.js';

const HOOK_NAME = 'lifecycle/sweep-stale-worktrees';

/**
 * Canonicalize a path for registry comparison. `git worktree list` reports
 * realpaths (e.g. /private/var/... on macOS) while scanned/recorded paths may
 * go through symlinks (/var/...) — plain resolve() would never match, which
 * for these sweeps could misclassify a LIVE worktree as stale.
 */
function canon(p: string): string {
  try {
    return realpathSync(p);
  } catch {
    return resolve(p);
  }
}

const MIN_AGE_MS = 60 * 60 * 1000; // 1 hour — race-protect in-flight worktree-add
const MAX_DEPTH_FILES = 3; // Find files up to 3 levels deep (avoids deep scans).

/**
 * Return paths registered with git worktree list, or `null` if the git call
 * itself failed (binary missing, repo corrupt, timeout). The caller treats
 * `null` as "skip this sweep cycle entirely" — fail-closed: if we cannot
 * verify the registry (predicate #1), do nothing.
 */
function registeredWorktrees(projectDir: string): Set<string> | null {
  try {
    const stdout = execFileSync('git', ['-C', projectDir, 'worktree', 'list', '--porcelain'], {
      encoding: 'utf8',
      timeout: 2000,
      windowsHide: true,
    });
    const paths = new Set<string>();
    for (const line of stdout.split('\n')) {
      if (line.startsWith('worktree ')) {
        paths.add(canon(line.slice('worktree '.length).trim()));
      }
    }
    return paths;
  } catch {
    return null;
  }
}

/**
 * Return true if `path` contains zero regular files (ignoring nested
 * empty dirs). Limited to MAX_DEPTH_FILES levels to bound the scan.
 */
function isEmptyOfFiles(path: string, depth = 0): boolean {
  // Conservative: treat unknown-depth subtree as NON-empty. The function name
  // says "is empty" → returning false here is the safe answer when we can't
  // verify. Returning true would risk false-positive deletion of a tree with
  // genuine content nested deeper than MAX_DEPTH_FILES levels.
  if (depth > MAX_DEPTH_FILES) return false;
  let entries: string[];
  try {
    entries = readdirSync(path);
  } catch {
    return false; // can't read — assume non-empty (safe)
  }
  for (const entry of entries) {
    // Skip well-known per-process detritus that may exist in aborted trees.
    // `.DS_Store` is a file (macOS Finder metadata); it must be skipped at the
    // top of the loop, BEFORE the isFile() check, or any aborted worktree
    // visited by Finder would be treated as non-empty. `.gitkeep` is the
    // placeholder the pre-#2335 enter-registrar dropped into orphan
    // `.worktrees/<name>/children/` shells — placeholder-only trees are
    // empty in the meaningful sense.
    if (entry === '.DS_Store' || entry === 'Thumbs.db' || entry === '.gitkeep') continue;

    const full = join(path, entry);
    let st: ReturnType<typeof statSync>;
    try {
      st = statSync(full);
    } catch {
      continue; // racey delete — skip
    }
    if (st.isFile() || st.isSymbolicLink()) return false;
    if (st.isDirectory()) {
      if (!isEmptyOfFiles(full, depth + 1)) return false;
    }
  }
  return true;
}

/**
 * Sweep orphan shells INSIDE `<projectDir>/.worktrees/` (#2335). Failed
 * Agent(isolation:"worktree") spawns on the pre-#2335 hook chain left
 * `.worktrees/<name>/children/.gitkeep` shells that were never registered
 * with git. Predicates: not registered, older than 1h, and empty of real
 * files (`.gitkeep` placeholders ignored).
 */
export function sweepWorktreeShells(projectDir: string, ctx: HookContext): number {
  const worktreesDir = join(resolve(projectDir), '.worktrees');
  if (!existsSync(worktreesDir)) return 0;

  const registered = registeredWorktrees(resolve(projectDir));
  if (registered === null) {
    ctx.log(HOOK_NAME, 'skipping .worktrees sweep — `git worktree list` failed');
    return 0;
  }

  let entries: string[];
  try {
    entries = readdirSync(worktreesDir);
  } catch {
    return 0;
  }

  const now = Date.now();
  let removed = 0;
  for (const entry of entries) {
    const fullPath = resolve(worktreesDir, entry);
    if (registered.has(canon(fullPath))) continue;

    let st: ReturnType<typeof statSync>;
    try {
      st = statSync(fullPath);
    } catch {
      continue;
    }
    if (!st.isDirectory()) continue;
    if (now - st.mtimeMs < MIN_AGE_MS) continue;
    if (!isEmptyOfFiles(fullPath)) continue;

    try {
      rmSync(fullPath, { recursive: true, force: true });
      removed++;
      ctx.log(HOOK_NAME, `removed orphan .worktrees shell: ${fullPath}`);
    } catch (err) {
      ctx.log(HOOK_NAME, `rm failed for ${fullPath}: ${(err as Error).message}`);
    }
  }
  return removed;
}

/**
 * Sweep stale pending-link markers in `.claude/state/worktree-pending/`
 * (#2335). Markers are written at WorktreeCreate and consumed by the
 * exit-finalizer at WorktreeRemove — when creation failed, no remove ever
 * fires and the marker leaks forever. A marker is stale when it is older
 * than 1h AND its recorded worktree_path is not a registered worktree.
 */
export function sweepPendingMarkers(projectDir: string, ctx: HookContext): number {
  const pendingDir = join(resolve(projectDir), '.claude', 'state', 'worktree-pending');
  if (!existsSync(pendingDir)) return 0;

  const registered = registeredWorktrees(resolve(projectDir));
  if (registered === null) {
    ctx.log(HOOK_NAME, 'skipping pending-marker sweep — `git worktree list` failed');
    return 0;
  }

  let entries: string[];
  try {
    entries = readdirSync(pendingDir);
  } catch {
    return 0;
  }

  const now = Date.now();
  let removed = 0;
  for (const entry of entries) {
    if (!entry.endsWith('.json')) continue;
    const fullPath = join(pendingDir, entry);

    let st: ReturnType<typeof statSync>;
    try {
      st = statSync(fullPath);
    } catch {
      continue;
    }
    if (!st.isFile()) continue;
    if (now - st.mtimeMs < MIN_AGE_MS) continue;

    // Resolve the marker's recorded worktree; unparseable markers count as
    // stale (they can never be matched by the exit-finalizer either).
    let worktreePath: string | null = null;
    try {
      const parsed = JSON.parse(readFileSync(fullPath, 'utf8'));
      if (typeof parsed?.worktree_path === 'string') worktreePath = canon(parsed.worktree_path);
    } catch {
      /* unparseable — treat as stale */
    }
    if (worktreePath && registered.has(worktreePath)) continue;

    try {
      rmSync(fullPath, { force: true });
      removed++;
      ctx.log(HOOK_NAME, `removed stale pending marker: ${fullPath}`);
    } catch (err) {
      ctx.log(HOOK_NAME, `rm failed for ${fullPath}: ${(err as Error).message}`);
    }
  }
  return removed;
}

export function sweepStaleWorktrees(
  _input: HookInput,
  ctx: HookContext = NOOP_CTX,
): HookResult {
  if (process.env.ORK_NO_STALE_SWEEP === '1') {
    return outputSilentSuccess();
  }

  const projectDir = getProjectDir();
  try {
    const removed =
      sweepWorktreeShells(projectDir, ctx) +
      sweepPendingMarkers(projectDir, ctx);
    if (removed > 0) {
      ctx.log(HOOK_NAME, `sweep complete: ${removed} stale worktree artifact(s) removed`);
    }
  } catch (err) {
    // Hook must never block CC — swallow + log.  // silent: known-noise
    ctx.log(HOOK_NAME, `sweep error: ${(err as Error).message}`);
  }

  return outputSilentSuccess();
}

// Re-exports so tests can poke internals without exporting from index.
export const __internals = {
  registeredWorktrees,
  isEmptyOfFiles,
  sweepWorktreeShells,
  sweepPendingMarkers,
  MIN_AGE_MS,
};
